#include "OlfactoryPersistenceEngine.h"
#include <algorithm>
namespace dnxr { OlfactoryPersistenceState OlfactoryPersistenceEngine::update(const OlfactoryRequest& r,double dt){ state_.exposureMs+=r.intensity>0?static_cast<float>(dt):0; if(!r.contextValid) return state_={0,state_.adaptation,state_.crossContamination,state_.exposureMs,false,"olfactory_context_invalid"}; if(state_.exposureMs>30000) return state_={0,state_.adaptation,state_.crossContamination,state_.exposureMs,false,"olfactory_exposure_limit"}; state_.adaptation=std::clamp(state_.adaptation+r.intensity*0.001f,0.0f,0.5f); state_.crossContamination=std::clamp(state_.crossContamination*0.98f+r.intensity*0.01f,0.0f,0.25f); state_.emittedIntensity=std::clamp(r.intensity-state_.adaptation-state_.crossContamination,0.0f,0.12f); state_.allowed=true; state_.reason="ok"; return state_; } }
